import{_ as e,o as p,c as o,a3 as s}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"1.6智能最大毛产","description":"","frontmatter":{"translationSource":{"title":"1.6智能最大毛产","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}]]},"headers":[],"relativePath":"zh/full-storage-oscillation-plan.md","filePath":"zh/page-JEibHxjUhjwaznRy5jp6oc.md"}'),i={name:"zh/full-storage-oscillation-plan.md"};function r(l,a,t,c,n,d){return p(),o("div",null,[...a[0]||(a[0]=[s(`<div class="logistics-content"><h1 id="_1-6智能最大毛产" tabindex="-1">1.6智能最大毛产 <a class="header-anchor" href="#_1-6智能最大毛产" aria-label="Permalink to &quot;1\\.6智能最大毛产&quot;">​</a></h1><blockquote><p>源页面 ID：<code>JEibHxjUhjwaznRy5jp6oc</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span class="mark-red"><strong>#言：我息壤模块呢？</strong></span></p><p>需求：</p><p>景玉谷12双口息壤，自启动12双口9准入口方案已做好，赤石点：设备数爆炸</p><p>其他部分：</p><p>应龙关去掉息壤加压，自连暗管外置，加东西（分离芯）</p><p>主基地待压缩（精炼炉，污水处理垃圾桶，壤晶线，炼铁磨粉分离芯，半速电池/，息壤震荡/，息壤液气转化/，息壤总线/，重息壤/）</p><p><span id="source-block-wt8iPy0gMDFywV7KEmhkoR"></span></p><h2 id="视频文案" tabindex="-1">视频文案 <a class="header-anchor" href="#视频文案" aria-label="Permalink to &quot;视频文案&quot;">​</a></h2><p><span id="source-block-YS3tBMxxg8McQAfMF35GpN"></span></p><h3 id="产线展示" tabindex="-1">产线展示 <a class="header-anchor" href="#产线展示" aria-label="Permalink to &quot;产线展示&quot;">​</a></h3><p>这一代对上一代的超越</p><p>更详细的功能介绍，尤其是插件演示</p><p>对观众的期许：比如说在评论区留下正面言论、希望答疑主要前往答疑网站和群聊并表达我们缺乏一一回复能力、注意到评论区甚至群内群友有很多并不正确的回复先肯定精神再指出错误的回复会造成困扰最后并不一棒子打死而是进一步建议有问题多去群/答疑网站并以答疑人员回答为准——虽然答疑人员不一定绝对正确但是不可否认的是他们比多数人更加熟悉产线并随时可以转接开发人员</p><p><span id="source-block-UU4P5kkrLs4f54xy23COub"></span></p><h3 id="产线讲解" tabindex="-1">产线讲解 <a class="header-anchor" href="#产线讲解" aria-label="Permalink to &quot;产线讲解&quot;">​</a></h3><p>模块简述</p><p>自动配平路径讲解</p><p><span id="source-block-VjRatZPY7VytfwEPSU53Zl"></span></p><h3 id="安装教程" tabindex="-1">安装教程 <a class="header-anchor" href="#安装教程" aria-label="Permalink to &quot;安装教程&quot;">​</a></h3><p><span id="source-block-0rfOwq29K0j4iJLxK2zROW"></span></p><h2 id="产线布局" tabindex="-1">产线布局 <a class="header-anchor" href="#产线布局" aria-label="Permalink to &quot;产线布局&quot;">​</a></h2><p><span id="source-block-pZevVPXGlCFmWxYpA22zV7"></span></p><h3 id="景玉谷" tabindex="-1">景玉谷 <a class="header-anchor" href="#景玉谷" aria-label="Permalink to &quot;景玉谷&quot;">​</a></h3><p><strong>目前主要制约：设备数量</strong></p><p>12双口息壤（必要）</p><p>2分离芯（必要）</p><p>3赤铜精炼（加压入库、溢流粉碎、固定粉碎都可以且可混用）（共2碎的话会非常好）（必要）</p><p>芽针/锦草种植-采种-粉碎组各一带自启动（必要）</p><p>蓝铁4精炼溢流3粉碎</p><p>零件机3灼1赫1蓝铁</p><p>灼铜装备元件机</p><p>中电（可选）（可以是砂叶也可以是封装）</p><p><span id="source-block-DWQoslYRbo23aoBVXH3XsK"></span></p><h4 id="蓝图" tabindex="-1">蓝图 <a class="header-anchor" href="#蓝图" aria-label="Permalink to &quot;蓝图&quot;">​</a></h4><p>10.28成果备选</p><p>13x286</p><p>EF01o5u21aiU362EIieO</p><p>EF01A67024u8eEUI9ieO</p><p>EF014AE7uI60O3eIE71A 175少两个清水标签 注：没有蓝铁零件</p><p>ss</p><p>EF015i2O176iIuoeIoe</p><p>EF01ao60534oiA0oe5e</p><p>EF015i2O176iIu4eIoe 175 注：没有蓝铁零件</p><p>13x286 1改 176补了打粉的一水 修正打粉暖机植物位置 加了蓝铁零件机 只改了上中两个蓝图</p><p>EF013Eo5097iIaAA0579</p><p>EF01U9eaE23oiO3I7Oa8</p><p>同上EF015i2O176iIu4eIoe</p><p>bear佬</p><p>EF015i2UO2EA1ua0eIoe</p><p>EF012UOe4O579855eIOo</p><p>EF014AE75EOU637UEa1A 178加滑索架标签完整有空间塞暗管 注：没有蓝铁零件</p><p>F.E.I.</p><p>EF01o5uIEue7o69AIieO</p><p>EF01i1UA0Uo8i26672U4</p><p>EF0170ie6i3u7513O0Ai借灵感156标签完整全暗管加滑索 注：赤铜块未粉碎</p><p>新改动：污水管全内置</p><p>13x286 旧图1改留档 注：没有装备机</p><p>EF01I43E61A789E25o08</p><p>EF01I43E61A789Eu5o08</p><p>EF01ao6uie529AO7oe5e</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4371b02670b69e21.q90-e718c507b8760ce4.webp" alt="16智能最大毛产"></p><pre><code>  二改 159→156蓝图右上水管电桩换位置省1物流桥 左中分离芯息壤从烘炉优先出下方赤铜块交叉省1物流桥 装备原件机消耗5s一个重息壤单带就够省1准入口
</code></pre><p><span id="source-block-tkw1iLW0nUBPYwoeRyJccp"></span></p><h3 id="主基地" tabindex="-1">主基地 <a class="header-anchor" href="#主基地" aria-label="Permalink to &quot;主基地&quot;">​</a></h3><p>息壤液震荡（4池</p><p>固定2池兼容打粉，可能耦合小药（对了，息壤池到底要不要兼容农场相关，要不蒜了吧</p><p>4息壤气液气</p><p>息壤气水气混产</p><p>抗一切壤晶</p><p>赤铜精炼溢流打粉12</p><p>赤铜精炼双带2耦合垃圾桶</p><p>蓝铁块和蓝铁零件为起点的小药产线</p><p>中电</p><p><span id="source-block-krXKbnL5O0kAIMgiAR5mXr"></span></p><h3 id="应龙关" tabindex="-1">应龙关 <a class="header-anchor" href="#应龙关" aria-label="Permalink to &quot;应龙关&quot;">​</a></h3><p>暗管外置——固气机改溢流、分离芯</p><p><span id="source-block-Ces5lBPzmHuwJoEt14KUwj"></span></p><h4 id="蓝图-1" tabindex="-1">蓝图 <a class="header-anchor" href="#蓝图-1" aria-label="Permalink to &quot;蓝图&quot;">​</a></h4><p>《明日方舟：终末地》蓝图 [1]分享码EF012UOe9a3UA8U4eIOo 请复制后前往游戏中使用。<br> 《明日方舟：终末地》蓝图 [2]分享码EF018OI4eAaOE13uUI73 请复制后前往游戏中使用。<br> 《明日方舟：终末地》蓝图 [3]分享码EF01Oe4Aa6oe7IuE9oe4 请复制后前往游戏中使用。<br> 《明日方舟：终末地》蓝图 [4]分享码EF0193aoE573ue4E5uI2 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8878fe3704f1d2ed.jpeg" alt="16智能最大毛产"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-454d47cf4cf6ae09.jpeg" alt="16智能最大毛产"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a289fcc8acabc17a.q90-5c57931e17a963fb.webp" alt="16智能最大毛产"></p><p><span id="source-block-wtaH6muc44xSRMXmWrcqDs"></span></p><h3 id="首墩" tabindex="-1">首墩 <a class="header-anchor" href="#首墩" aria-label="Permalink to &quot;首墩&quot;">​</a></h3><p><span id="source-block-6SkebfDdeH1om407PRb3Pg"></span></p><h5 id="日用品插件" tabindex="-1">日用品插件 <a class="header-anchor" href="#日用品插件" aria-label="Permalink to &quot;日用品插件&quot;">​</a></h5><p><span id="source-block-0kspTcZc9FCeTSNB1Zsg97"></span></p><h5 id="紫药、息壤液罐装、重息壤液罐装、赤铜零件、小电、待补充" tabindex="-1">紫药、息壤液罐装、重息壤液罐装、赤铜零件、小电、待补充 <a class="header-anchor" href="#紫药、息壤液罐装、重息壤液罐装、赤铜零件、小电、待补充" aria-label="Permalink to &quot;紫药、息壤液罐装、重息壤液罐装、赤铜零件、小电、待补充&quot;">​</a></h5><p><span id="source-block-5Fcbr8mwQYsbQVWw3qnHU8"></span></p><h5 id="缘缘庄插件" tabindex="-1">缘缘庄插件 <a class="header-anchor" href="#缘缘庄插件" aria-label="Permalink to &quot;缘缘庄插件&quot;">​</a></h5><p><span id="source-block-FBtPNvsLFil3Wtwnz99gI5"></span></p><h2 id="散装模块" tabindex="-1">散装模块 <a class="header-anchor" href="#散装模块" aria-label="Permalink to &quot;散装模块&quot;">​</a></h2><p><span id="source-block-Z5vNKLZ8EC4EtG1KTC6C8F"></span></p><h3 id="壤晶线" tabindex="-1">壤晶线 <a class="header-anchor" href="#壤晶线" aria-label="Permalink to &quot;壤晶线&quot;">​</a></h3><p>《明日方舟：终末地》蓝图 [单边抗一切壤晶]分享码EF01u28U5Ie870a7AoOU 请复制后前往游戏中使用。</p><p><span id="source-block-HUOTrAo1XGkxDqwoWUNxYD"></span></p><h3 id="重息壤" tabindex="-1">重息壤 <a class="header-anchor" href="#重息壤" aria-label="Permalink to &quot;重息壤&quot;">​</a></h3><p>《明日方舟：终末地》蓝图 [四核重息壤]分享码EF01I43EaUUUu9o45o08 请复制后前往游戏中使用。</p><p><span id="source-block-A8b2BmNv3r8OczTH6mi4LB"></span></p><h3 id="铜处理" tabindex="-1">铜处理 <a class="header-anchor" href="#铜处理" aria-label="Permalink to &quot;铜处理&quot;">​</a></h3><p>《明日方舟：终末地》蓝图 [临时精炼]分享码EF013Eo56eee8a510579 请复制后前往游戏中使用。<br> 《明日方舟：终末地》蓝图 [分离芯]分享码EF01U9ea48887OiI7Oa8 请复制后前往游戏中使用。</p><p><span id="source-block-h3O6ZElo5DYvpwQqWExr9k"></span></p><h3 id="蓝铁处理" tabindex="-1">蓝铁处理 <a class="header-anchor" href="#蓝铁处理" aria-label="Permalink to &quot;蓝铁处理&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abd42c7b4bee2263.q90-fcf8ba08a760fb80.webp" alt="16智能最大毛产"></p><div class="logistics-image-caption" data-source-block="K6uojhba5PhZY4h7JS1DHr"><p>赫塔-蓝铁精炼及打粉</p></div><p><span id="source-block-V6Z6WWObS8Sp9VROKaVcgK"></span></p><h3 id="息壤" tabindex="-1">息壤 <a class="header-anchor" href="#息壤" aria-label="Permalink to &quot;息壤&quot;">​</a></h3><p><span class="mark-red">东西呢快点端上来！！！</span></p><p><span id="source-block-PSVH9EWPl3In6oiZbgmPV9"></span></p><h3 id="息壤液满仓震荡模块" tabindex="-1">息壤液满仓震荡模块 <a class="header-anchor" href="#息壤液满仓震荡模块" aria-label="Permalink to &quot;息壤液满仓震荡模块&quot;">​</a></h3><p><span id="source-block-qFVfEvK9jO1NhKefnV1XSG"></span></p><h4 id="控息壤" tabindex="-1">控息壤 <a class="header-anchor" href="#控息壤" aria-label="Permalink to &quot;控息壤&quot;">​</a></h4><p><span id="source-block-GiL6uZNnTppYmPRchrcBmr"></span></p><h4 id="控水" tabindex="-1">控水 <a class="header-anchor" href="#控水" aria-label="Permalink to &quot;控水&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7c56052227e27422.q90-4b211e99002b0a11.webp" alt="16智能最大毛产"></p><p>填充物：除了最左断电箱都填充250锦草、断电池填充4杂物和传送带长的锦草种子</p><p>应该是省了非常多设备数了，代价仅是4管道件。不过我还没压缩（（</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-280aed2b84bcdf55.q90-653ca728b79d0e3c.webp" alt="16智能最大毛产"></p><div class="logistics-image-caption" data-source-block="cXD5Oa5klddFZoIT9qBbsU"><p>优先级如图所示</p></div><p>初步压缩完成；断电池制备较久，不知道要不要优化</p><p><s>《明日方舟：终末地》蓝图 [武陵断电池]分享码EF015i2eii8O2uaa0eIoe 请复制后前往游戏中使用。</s></p><p><s>《明日方舟：终末地》蓝图 [震荡息壤液]分享码EF01E75U77u25o56E3uIa 请复制后前往游戏中使用。</s></p><p><strong>已被君大人优化</strong></p><p>液体满仓震荡EF01u28O96Ueo00EAoOU</p><p>照图摆的应该没问题</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7cbaefd4b1cd885b.q90-fe1d3cb93912abf0.webp" alt="16智能最大毛产"></p><p><span id="source-block-KGoyl1IImSJZnibL6nDWDF"></span></p><h3 id="息壤气" tabindex="-1">息壤气 <a class="header-anchor" href="#息壤气" aria-label="Permalink to &quot;息壤气&quot;">​</a></h3><p><span id="source-block-bd3KuSLybokw1RKWgQVoj2"></span></p><h4 id="四核息壤气" tabindex="-1">四核息壤气 <a class="header-anchor" href="#四核息壤气" aria-label="Permalink to &quot;四核息壤气&quot;">​</a></h4><p><span id="source-block-VI0K6hIG0gZuPIloebTgyJ"></span></p><h4 id="息壤气水气混产" tabindex="-1">息壤气水气混产 <a class="header-anchor" href="#息壤气水气混产" aria-label="Permalink to &quot;息壤气水气混产&quot;">​</a></h4><p><span id="source-block-kWb3Jsyk9OsCbMnCJ8ZB5S"></span></p><h4 id="五核息壤气-备选" tabindex="-1">五核息壤气（备选 <a class="header-anchor" href="#五核息壤气-备选" aria-label="Permalink to &quot;五核息壤气（备选&quot;">​</a></h4><p>《明日方舟：终末地》蓝图 [五液气]分享码EF013Eou460iuau3U0579 请复制后前往游戏中使用。</p><p><span id="source-block-I6zAY6W2XBcbVSabVa6w2s"></span></p><h2 id="北部禁区息壤气拉法" tabindex="-1">北部禁区息壤气拉法 <a class="header-anchor" href="#北部禁区息壤气拉法" aria-label="Permalink to &quot;北部禁区息壤气拉法&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-7ed15289ffeacc9c.q90-899dc838aff2d2a0.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-9e171bac57e90c75.q90-afaeee960e8ec8ac.webp" alt="图片"></td></tr></tbody></table><p><span class="mark-grey">左侧可以直接传送，多一对暗管，右侧需要跑图，省一对暗管</span></p></div>`,1)])])}const u=e(i,[["render",r]]);export{b as __pageData,u as default};
